const nb = Math.round(bays), nl = Math.round(lifts), w = bay_width, h = lift_height, D = depth / 2;
const top = nl * h + 1.0;
const line = (a, b) => addprim(0, 'polyline', [addpoint(0, a), addpoint(0, b)]);
for (let i = 0; i <= nb; i++) for (const z of [-D, D]) line([i * w, 0.02, z], [i * w, top, z]);
for (let l = 1; l <= nl; l++) {
  const y = l * h;
  for (const z of [-D, D]) line([-0.15, y, z], [nb * w + 0.15, y, z]);
  for (let i = 0; i <= nb; i++) line([i * w, y - 0.05, -D - 0.15], [i * w, y - 0.05, D + 0.15]);
}
for (const z of [-D, D]) { line([-0.15, nl * h + 0.5, z], [nb * w + 0.15, nl * h + 0.5, z]); line([-0.15, nl * h + 1.0 - 0.02, z], [nb * w + 0.15, nl * h + 1.0 - 0.02, z]); }
line([-0.15, 0.25, -D], [nb * w + 0.15, 0.25, -D]); line([-0.15, 0.25, D], [nb * w + 0.15, 0.25, D]);
if (braces) for (let i = 0; i < nb; i++) for (let l = 0; l < nl; l++) {
  const up = (i + l) % 2 === 0;
  line([i * w, l * h + (up ? 0.25 : h), D + 0.06], [(i + 1) * w, l * h + (up ? h : 0.25), D + 0.06]);
}

const nb = Math.round(bays), nl = Math.round(lifts), w = bay_width, h = lift_height, D = depth;
const n = Math.max(2, Math.floor((D - 0.05) / 0.23)), bw = 0.22, start = -((n - 1) * 0.23) / 2;
for (let l = 1; l <= nl; l++) for (let i = 0; i < nb; i++) for (let k = 0; k < n; k++) {
  const q = addpoint(0, [i * w + w / 2, l * h + 0.0, start + k * 0.23]);
  setpointattrib(0, 'scale', q, [w + 0.18, 0.038, bw]);
  setpointattrib(0, 'tint', q, 0.85 + 0.25 * rand(l, i, k));
}
